#!/usr/bin/env python3
import sys

print("Running tight math loop. Press Ctrl+C to exit.")
try:
    x = 1.0
    while True:
        # Simple mathematical operations
        x = x * 1.000001
        x = x / 1.0000005

        # Prevent overflow
        if x > 1000000.0:
            x = 1.0

except KeyboardInterrupt:
    print("\nExiting...")
    sys.exit(0)
